#!/usr/bin/env bash
# =============================================================
# Frame Processing and Caption Formatting
# =============================================================

set -euo pipefail

# Convert frame number into a formatted timestamp (HH:MM:SS)
# Prioritizes exact timestamp from timestamps.json (generated by efioex6),
# and falls back to calculating via frame number and fps.
calculate_timestamp() {
    local frame="$1"
    local fps="$2"

    # Step 1: Check timestamps.json generated by efioex6
    if [ -f "timestamps.json" ]; then
        local exact_ts
        exact_ts=$(jq -r ".\"$frame\" // empty" timestamps.json 2>/dev/null || echo "")
        if [ -n "$exact_ts" ] && [ "$exact_ts" != "null" ]; then
            echo "$exact_ts"
            return
        fi
    fi

    # Step 2: Fallback calculation via frame number and fps
    if [ "$frame" -le 0 ]; then
        echo "00:00:00"
        return
    fi

    # Calculate total seconds using bc
    local total_seconds
    total_seconds=$(echo "scale=0; ($frame - 1) / $fps" | bc -l 2>/dev/null || echo "0")

    local hours=$((total_seconds / 3600))
    local minutes=$(((total_seconds % 3600) / 60))
    local seconds=$((total_seconds % 60))

    printf "%02d:%02d:%02d" "$hours" "$minutes" "$seconds"
}

# Safely replace template variables without using eval
render_caption() {
    local template="$1"
    local current_frame="$2"
    local timestamp="$3"

    local caption="$template"

    # Replace placeholders safely using bash string substitution
    caption="${caption//\{anime_name\}/${anime_name:-}}"
    caption="${caption//\{season\}/${season:-}}"
    caption="${caption//\{episode\}/${episode:-}}"
    caption="${caption//\{current_frame\}/$current_frame}"
    caption="${caption//\{total_frame\}/${total_frame:-}}"
    caption="${caption//\{timestamp\}/$timestamp}"

    echo "$caption"
}
